import{_ as o,a0 as t,w as u,s as x,I as a,x as n,a1 as p,A as l,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"使用 Fluxbox 桌面作为你的窗口管理器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Fluxbox 桌面作为你的窗口管理器 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Fluxbox 桌面作为你的窗口管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Fluxbox 桌面作为你的窗口管理器 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191209 Use the Fluxbox Linux desktop as your window manager","title":"使用 Fluxbox 桌面作为你的窗口管理器","tag":"202004","desc":""},"relativePath":"202004/20191209 Use the Fluxbox Linux desktop as your window manager.md","filePath":"[post].md"}'),r={name:"202004/20191209 Use the Fluxbox Linux desktop as your window manager.md"};function d(b,s,f,c,m,g){const e=t("Link");return u(),x("div",null,[s[26]||(s[26]=a("h1",{id:"使用-fluxbox-桌面作为你的窗口管理器",tabindex:"-1"},[n("使用 Fluxbox 桌面作为你的窗口管理器 "),a("a",{class:"header-anchor",href:"#使用-fluxbox-桌面作为你的窗口管理器","aria-label":"Permalink to “使用 Fluxbox 桌面作为你的窗口管理器”"},"​")],-1)),s[27]||(s[27]=a("blockquote",null,[a("p",null,"本文是 24 天 Linux 桌面特别系列的一部分。Fluxbox 对系统资源的占用非常轻量，但它拥有重要的 Linux 桌面功能，让你的用户体验轻松、高效、快捷。")],-1)),s[28]||(s[28]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/07/113105p0ng5skkn5kmvdm0.jpg",alt:""})],-1)),s[29]||(s[29]=a("p",null,"桌面的概念可谓是仁者见仁智者见智。很多人把桌面看作一个家的基地，或者一个舒适的客厅，甚至是一个字面意义上的桌面，在其中放置着他们经常使用的记事本、最好的笔和铅笔，还有他们最喜欢的咖啡杯。KDE、 GNOME、Pantheon 等等在 Linux 上提供了这种舒适的生活方式。",-1)),a("p",null,[s[1]||(s[1]=n("但是对一些用户来说，桌面只是一个空荡荡的显示器空间，这是还没有任何可以自由浮动的应用程序窗口直接投射到他们的视网膜上的副作用。对于这些用户来说，桌面是一个空的空间，他们可以在上面运行应用程序 —— 无论是大型办公软件和图形套件，还是一个简单的终端窗口，或是来管理服务的托盘小程序。这种操作 ",-1)),p(e,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:l(()=>[...s[0]||(s[0]=[n("POSIX",-1)])]),_:1}),s[2]||(s[2]=n(" 计算机的模式由来已久，该家族树的一支是 *box 窗口管理器：Blackbox、Fluxbox 和 Openbox。",-1))]),a("p",null,[p(e,{href:"http://fluxbox.org"},{default:l(()=>[...s[3]||(s[3]=[n("Fluxbox",-1)])]),_:1}),s[4]||(s[4]=n(" 是一个 X11 系统的窗口管理器，它基于一个较老的名为 Blackbox 的项目。当我发现 Linux 时，Blackbox 的开发已进入衰退期，因此我就喜欢上了 Fluxbox ，此后我至少在一个以上的常用的系统上使用过它。它是用 C++ 编写的，并在 MIT 开源许可证下授权。",-1))]),s[30]||(s[30]=a("h3",{id:"安装-fluxbox",tabindex:"-1"},[n("安装 Fluxbox "),a("a",{class:"header-anchor",href:"#安装-fluxbox","aria-label":"Permalink to “安装 Fluxbox”"},"​")],-1)),a("p",null,[s[6]||(s[6]=n("你很可能会在你的 Linux 发行版的软件库中找到 Fluxbox，但是你也可以在 ",-1)),p(e,{href:"http://fluxbox.org/download/"},{default:l(()=>[...s[5]||(s[5]=[n("Fluxbox.org",-1)])]),_:1}),s[7]||(s[7]=n(" 上找到它。如果你正在运行另外一个桌面，在同一个系统上安装 Fluxbox 是安全的，因为 Fluxbox 不会预设任何配置或附带的应用程序。",-1))]),s[31]||(s[31]=i('<p>在安装 Fluxbox 后，注销你当前的桌面会话，以便你可以登录一个新的桌面会话。默认情况下，你的桌面会话管理器 (KDM、GDM、LightDM 或 XDM，取决于你的安装设置) 将继续让登录到之前的桌面，所以你在登录前必需要覆盖上一个桌面。</p><p>使用 GDM 覆盖一个桌面：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_0.jpg" alt="在 GDM 中选择你的桌面会话" title="Select your desktop session in GDM"></p><p>或者使用 KDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm.jpg" alt="使用 KDM 选择你的桌面会话" title="Select your desktop session with KDM"></p><h3 id="配置-fluxbox-桌面" tabindex="-1">配置 Fluxbox 桌面 <a class="header-anchor" href="#配置-fluxbox-桌面" aria-label="Permalink to “配置 Fluxbox 桌面”">​</a></h3><p>当你第一次登录到桌面时，屏幕基本是空的，因为 Fluxbox 提供的所有东西是面板（用于任务栏、系统托盘等等）和用于应用程序窗口的窗口装饰品。</p><p><img src="https://opensource.com/sites/default/files/advent-fluxbox-default.jpg" alt="在 CentOS 7 上的默认 Fluxbox 配置" title="Default Fluxbox configuration on CentOS 7"></p><p>如果你的发行版提供一个简单的 Fluxbox 桌面，你可以使用 <code>feh</code> 命令（你可能需要从你的发行版的软件库中安装它）来为你的桌面设置背景。这个命令有几个用于设置背景的选项，包括使用你选择的墙纸来填充屏幕的 <code>--bg-fill</code> 选项，来按比例缩放的 <code>--bg-scale</code> 等等选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ feh --bg-fill ~/photo/oamaru/leaf-spiral.jpg</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/advent-fluxbox-green.jpg" alt="应用主题的 Fluxbox " title="Fluxbox with a theme applied"></p><p>默认情况下，Fluxbox 自动生成一个菜单，在桌面上任意位置右键单击可用该菜单，这给予你访问应用程序的能力。根据你的发行版的不同，这个菜单可能非常小，也可能列出 <code>/usr/share/applications</code> 目录中的所有启动程序。</p><p>Fluxbox 配置是在文本文件中设置的，这些文本文件包含在 <code>$HOME/.fluxbox</code> 目录中。你可以：</p><ul><li>在 <code>keys</code> 中设置键盘快捷键</li><li>在 <code>startup</code> 中启动的服务和应用程序</li><li>在 <code>init</code> 设置桌面首选项（例如工作区数量、面板位置等等）</li><li>在 <code>menu</code> 中设置菜单项</li></ul>',14)),a("p",null,[s[9]||(s[9]=n("该文本配置文件非常易于推断，但是你也可以（并且是应该）阅读 Fluxbox 的",-1)),p(e,{href:"http://fluxbox.org/features/"},{default:l(()=>[...s[8]||(s[8]=[n("文档",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[32]||(s[32]=i(`<p>例如，这是我的典型菜单（或者说至少有它的基本结构）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 为使用你自己的菜单，复制这些文本到 ~/.fluxbox/menu，然后编辑</span></span>
<span class="line"><span># ~/.fluxbox/init ，并更改 session.menuFile 文件路径到 ~/.fluxbox/menu</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[begin] (fluxkbox)</span></span>
<span class="line"><span> [submenu] (apps) {}</span></span>
<span class="line"><span>  [submenu] (txt) {}</span></span>
<span class="line"><span>   [exec] (Emacs 23 (text\\)) { x-terminal-emulator -T &quot;Emacs (text)&quot; -e /usr/bin/emacs -nw} &lt;&gt;</span></span>
<span class="line"><span>   [exec] (Emacs (X11\\)) {/usr/bin/emacs} &lt;&gt;</span></span>
<span class="line"><span>   [exec] (LibreOffice) {/usr/bin/libreoffice}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (code) {}</span></span>
<span class="line"><span>   [exec] (qtCreator) {/usr/bin/qtcreator}</span></span>
<span class="line"><span>   [exec] (eclipse) {/usr/bin/eclipse}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (graphics) {}</span></span>
<span class="line"><span>   [exec] (ksnapshot) {/usr/bin/ksnapshot}</span></span>
<span class="line"><span>   [exec] (gimp) {/usr/bin/gimp}</span></span>
<span class="line"><span>   [exec] (blender) {/usr/bin/blender}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (files) {}</span></span>
<span class="line"><span>   [exec] (dolphin) {/usr/bin/dolphin}</span></span>
<span class="line"><span>   [exec] (konqueror) { /usr/bin/kfmclient openURL $HOME }</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span>  [submenu] (network) {}</span></span>
<span class="line"><span>   [exec] (firefox) {/usr/bin/firefox}</span></span>
<span class="line"><span>   [exec] (konqueror) {/usr/bin/konqueror}</span></span>
<span class="line"><span>  [end]</span></span>
<span class="line"><span> [end]</span></span>
<span class="line"><span>## 更改窗口管理器或工作环境</span></span>
<span class="line"><span>[submenu] (environments) {}</span></span>
<span class="line"><span> [restart] (flux)  {/usr/bin/startfluxbox}</span></span>
<span class="line"><span> [restart] (ratpoison)  {/usr/bin/ratpoison}</span></span>
<span class="line"><span> [exec] (openIndiana) {/home/kenlon/qemu/startSolaris.sh}</span></span>
<span class="line"><span>[end]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[config] (config)</span></span>
<span class="line"><span> [submenu] (styles) {}</span></span>
<span class="line"><span>  [stylesdir] (/usr/share/fluxbox/styles)</span></span>
<span class="line"><span>  [stylesdir] (~/.fluxbox/styles)</span></span>
<span class="line"><span> [end]</span></span>
<span class="line"><span>[workspaces] (workspaces)</span></span>
<span class="line"><span>[reconfig] (reconfigure)</span></span>
<span class="line"><span>[restart] (restart)</span></span>
<span class="line"><span>[exit] (exeunt)</span></span>
<span class="line"><span>[end]</span></span></code></pre></div><p>该菜单也提供一些首选项设置，例如，选择一个主题，从 Fluxbox 会话中重启或注销的能力。</p><p>我使用键盘快捷键来启动大多数的应用程序，这些快捷键写入到 <code>keys</code> 配置文件中。这里有一些示例（<code>Mod4</code> 按键是 <code>Super</code> 键，我使用其来指定全局快捷键）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 打开应用程序</span></span>
<span class="line"><span>Mod4 t :Exec konsole</span></span>
<span class="line"><span>Mod4 k :Exec konqueror</span></span>
<span class="line"><span>Mod4 z :Exec fbrun</span></span>
<span class="line"><span>Mod4 e :Exec emacs</span></span>
<span class="line"><span>Mod4 f :Exec firefox</span></span>
<span class="line"><span>Mod4 x :Exec urxvt</span></span>
<span class="line"><span>Mod4 d :Exec dolphin</span></span>
<span class="line"><span>Mod4 q :Exec xscreensaver-command -activate</span></span>
<span class="line"><span>Mod4 3 :Exec ksnapshot</span></span></code></pre></div><p>在这些快捷方式和一个打开的终端之间，在我工作日的大部分时间内很少使用鼠标，因此从一个控制器切换到另一个控制器不会浪费时间。并且因为 Fluxbox 很好地避开了控制器之间切换的方法，因此在其中操作没有一丝干扰。</p><h3 id="为什么你应该使用-fluxbox" tabindex="-1">为什么你应该使用 Fluxbox <a class="header-anchor" href="#为什么你应该使用-fluxbox" aria-label="Permalink to “为什么你应该使用 Fluxbox”">​</a></h3><p>Fluxbox 对系统资源的占用非常轻量，但是它拥有重要的功能，可以使你的用户体验轻松、快速、高效。它很容易定制，并且允许你定义你自己的工作流。你不必使用 Fluxbox 的面板，因为还有其它优秀的面板。你甚至可以鼠标中键点击并拖动两个独立的应用程序窗口到彼此之中，以便它们成为一个窗口，每个窗口都有自己的选项卡。</p><p>可能性是无穷的，所以今天就在你的 Linux 上尝试一下 Fluxbox 的简单稳定吧！</p><hr>`,10)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/19/12/fluxbox-linux-desktop"},{default:l(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/19/12/fluxbox-linux-desktop",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[13]||(s[13]=[n("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=n(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 译者：",-1)),p(e,{href:"https://github.com/robsean"},{default:l(()=>[...s[15]||(s[15]=[n("robsean",-1)])]),_:1}),s[20]||(s[20]=n(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...s[22]||(s[22]=[n("Linux中国",-1)])]),_:1}),s[25]||(s[25]=n(" 荣誉推出",-1))])])}const T=o(r,[["render",d]]);export{F as __pageData,T as default};
